INSERT INTO public.projects (slug, name, category, image_url, image_urls, blurb, tags, featured, published, sort)
VALUES
  ('aluminum-lure-mold', 'Aluminum Lure Mold', 'mechanical', '/projects/portfolio/aluminum-mold-lures-0.jpg', ARRAY['/projects/portfolio/aluminum-mold-lures-0.jpg', '/projects/portfolio/aluminum-mold-lures-1.jpg', '/projects/portfolio/aluminum-mold-lures-2.jpg', '/projects/portfolio/aluminum-mold-lures-3.jpg', '/projects/portfolio/aluminum-mold-lures-4.jpg'], 'A four-part casting mould for an elastic "Hedgehog" lure. Outer sections were thickened and inner sections narrowed so the complex geometry separates and releases without damaging the casting.', ARRAY['Tooling', 'Casting', 'Aluminium'], true, true, 80),
  ('protective-shoe-cover', 'Protective Shoe Cover', 'product', '/projects/portfolio/sock-0.jpg', ARRAY['/projects/portfolio/sock-0.jpg', '/projects/portfolio/sock-1.jpg', '/projects/portfolio/sock-2.jpg', '/projects/portfolio/sock-3.jpg', '/projects/portfolio/sock-4.jpg', '/projects/portfolio/sock-5.jpg'], 'A universal indoor overshoe that fits either foot in a single size, with an elastic ankle band for grip and transverse rubber strips underfoot to reduce slipping.', ARRAY['Product Design', 'Universal Fit', 'Elastomer'], false, true, 81),
  ('groomstick-beard-comb', 'GroomStick Beard Comb', 'product', '/projects/portfolio/groom-stick-0.jpg', ARRAY['/projects/portfolio/groom-stick-0.jpg', '/projects/portfolio/groom-stick-1.jpg', '/projects/portfolio/groom-stick-2.jpg', '/projects/portfolio/groom-stick-3.jpg', '/projects/portfolio/groom-stick-4.jpg', '/projects/portfolio/groom-stick-5.jpg'], 'A compact beard comb with an integrated lip balm holder. Tooth arrangement, curved profile and the balm cavity were reworked over several rounds to stay pocketable and print-friendly.', ARRAY['Product Design', '3D Print', 'Grooming'], false, true, 82),
  ('golf-divot-repair-tool', 'Golf Divot Repair Tool', 'product', '/projects/portfolio/divot-tool-0.jpg', ARRAY['/projects/portfolio/divot-tool-0.jpg', '/projects/portfolio/divot-tool-1.jpg', '/projects/portfolio/divot-tool-2.jpg', '/projects/portfolio/divot-tool-3.jpg', '/projects/portfolio/divot-tool-4.jpg', '/projects/portfolio/divot-tool-5.jpg'], 'A premium divot tool in minimalist vintage style. Thickness, prong design and the connection areas were revised for structural strength so the prongs resist bending in use.', ARRAY['Metal', 'Ergonomics', 'STEP / STL'], true, true, 83),
  ('cosplay-wing-arm-support', 'Cosplay Wing Arm Support', 'mechanical', '/projects/portfolio/arm-support-0.jpg', ARRAY['/projects/portfolio/arm-support-0.jpg', '/projects/portfolio/arm-support-1.jpg', '/projects/portfolio/arm-support-2.jpg', '/projects/portfolio/arm-support-3.jpg', '/projects/portfolio/arm-support-4.jpg', '/projects/portfolio/arm-support-5.jpg', '/projects/portfolio/arm-support-6.jpg', '/projects/portfolio/arm-support-7.jpg', '/projects/portfolio/arm-support-8.jpg', '/projects/portfolio/arm-support-9.jpg'], 'A six-piece sheet-metal arm support frame for cosplay wings — sketches converted to CAD, verified as a 3D assembly, then issued as dimensioned DWG drawings for laser cutting.', ARRAY['Sheet Metal', 'Laser Cutting', '2D DWG'], false, true, 84),
  ('fishing-hole-cover', 'Fishing Hole Cover', 'product', '/projects/portfolio/fishing-hole-cover-0.jpg', ARRAY['/projects/portfolio/fishing-hole-cover-0.jpg', '/projects/portfolio/fishing-hole-cover-1.jpg', '/projects/portfolio/fishing-hole-cover-2.jpg', '/projects/portfolio/fishing-hole-cover-3.jpg', '/projects/portfolio/fishing-hole-cover-4.jpg', '/projects/portfolio/fishing-hole-cover-5.jpg', '/projects/portfolio/fishing-hole-cover-6.jpg'], 'Housing and hinged lid assembly with clearances tuned so the cover opens freely while staying attached, plus external openings for LED lighting and a line passage when closed.', ARRAY['Assembly', 'Mechanism', 'Outdoor'], false, true, 85),
  ('gear-tooth-interference-fix', 'Gear Tooth Interference Fix', 'mechanical', '/projects/portfolio/gears-and-teeth-0.jpg', ARRAY['/projects/portfolio/gears-and-teeth-0.jpg', '/projects/portfolio/gears-and-teeth-1.jpg', '/projects/portfolio/gears-and-teeth-2.jpg', '/projects/portfolio/gears-and-teeth-3.jpg', '/projects/portfolio/gears-and-teeth-4.jpg', '/projects/portfolio/gears-and-teeth-5.jpg'], 'An existing gear train jammed on tooth collisions. We analysed the meshing, then supplied 36- and 37-tooth alternatives with reworked tooth profiles at the original diameter.', ARRAY['Gear Design', 'Analysis', 'Optimisation'], false, true, 86),
  ('golf-ball-mark-repair-tool', 'Golf Ball Mark Repair Tool', 'product', '/projects/portfolio/ball-mark-tool-0.jpg', ARRAY['/projects/portfolio/ball-mark-tool-0.jpg', '/projects/portfolio/ball-mark-tool-1.jpg', '/projects/portfolio/ball-mark-tool-2.jpg', '/projects/portfolio/ball-mark-tool-3.jpg', '/projects/portfolio/ball-mark-tool-4.jpg'], 'Full assembly of a sand/seed dispensing repair tool — housing, spring-loaded rod, refill cap and handle, with clearances set for smooth internal movement.', ARRAY['Mechanism', 'Assembly', 'Prototype'], false, true, 87),
  ('spin-digger', 'Spin Digger', 'product', '/projects/portfolio/spin-digger-0.jpg', ARRAY['/projects/portfolio/spin-digger-0.jpg', '/projects/portfolio/spin-digger-1.jpg', '/projects/portfolio/spin-digger-2.jpg', '/projects/portfolio/spin-digger-3.jpg', '/projects/portfolio/spin-digger-4.jpg', '/projects/portfolio/spin-digger-5.jpg', '/projects/portfolio/spin-digger-6.jpg', '/projects/portfolio/spin-digger-7.jpg', '/projects/portfolio/spin-digger-8.jpg', '/projects/portfolio/spin-digger-9.jpg', '/projects/portfolio/spin-digger-10.jpg'], 'Two concepts for joining a rubber top to a plastic body — a threaded version and a snap-fit click-lock — modelled in full so the customer could evaluate both.', ARRAY['Snap-fit', 'Concept Study', 'Product Design'], false, true, 88),
  ('cooler-cup-and-skate-cup', 'Cooler Cup & Skate Cup', 'product', '/projects/portfolio/cooler-and-skate-cup-0.jpg', ARRAY['/projects/portfolio/cooler-and-skate-cup-0.jpg', '/projects/portfolio/cooler-and-skate-cup-1.jpg', '/projects/portfolio/cooler-and-skate-cup-2.jpg', '/projects/portfolio/cooler-and-skate-cup-3.jpg', '/projects/portfolio/cooler-and-skate-cup-4.jpg', '/projects/portfolio/cooler-and-skate-cup-5.jpg', '/projects/portfolio/cooler-and-skate-cup-6.jpg', '/projects/portfolio/cooler-and-skate-cup-7.jpg'], 'Two drinkware models reconstructed entirely from reference photos and target capacities — no drawings or dimensions existed — with branding elements built into the CAD.', ARRAY['Concept-to-Part', 'Branding', 'Consumer'], true, true, 89),
  ('under-desk-device-pouch', 'Under-Desk Device Pouch', 'product', '/projects/portfolio/under-desk-storage-0.jpg', ARRAY['/projects/portfolio/under-desk-storage-0.jpg', '/projects/portfolio/under-desk-storage-1.jpg', '/projects/portfolio/under-desk-storage-2.jpg', '/projects/portfolio/under-desk-storage-3.jpg', '/projects/portfolio/under-desk-storage-4.jpg', '/projects/portfolio/under-desk-storage-5.jpg', '/projects/portfolio/under-desk-storage-6.jpg', '/projects/portfolio/under-desk-storage-7.jpg', '/projects/portfolio/under-desk-storage-8.jpg'], 'An under-desk storage pouch for portable electronics, taken from two competing concepts through repeated iterations on cavity size, finger-access slots and external fillets.', ARRAY['Product Design', 'Iteration', 'Office'], false, true, 90),
  ('yoga-block', 'Yoga Block', 'product', '/projects/portfolio/yoga-block-0.jpg', ARRAY['/projects/portfolio/yoga-block-0.jpg', '/projects/portfolio/yoga-block-1.jpg', '/projects/portfolio/yoga-block-2.jpg', '/projects/portfolio/yoga-block-3.jpg', '/projects/portfolio/yoga-block-4.jpg'], 'Modelled from sketches and reference photos rather than manufacturing documentation, so shape, proportion and cutout geometry were interpreted, then tuned for depth and side notches.', ARRAY['Concept-to-Part', 'Fitness', 'Consumer'], false, true, 91),
  ('steam-and-exhaust-manifold', 'Steam & Exhaust Manifold', 'mechanical', '/projects/portfolio/steam-exhaust-manifold-0.jpg', ARRAY['/projects/portfolio/steam-exhaust-manifold-0.jpg', '/projects/portfolio/steam-exhaust-manifold-1.jpg', '/projects/portfolio/steam-exhaust-manifold-2.jpg', '/projects/portfolio/steam-exhaust-manifold-3.jpg', '/projects/portfolio/steam-exhaust-manifold-4.jpg', '/projects/portfolio/steam-exhaust-manifold-5.jpg', '/projects/portfolio/steam-exhaust-manifold-6.jpg'], 'External geometry, internal passages, drilled and threaded features built from supplied drawings, then revised against photos of the manufactured part until CAD and hardware matched.', ARRAY['Industrial', 'Internal Passages', 'Drawings'], false, true, 92),
  ('intake-valve-cleaner', 'Intake Valve Cleaner', 'mechanical', '/projects/portfolio/intake-valve-cleaner-0.jpg', ARRAY['/projects/portfolio/intake-valve-cleaner-0.jpg', '/projects/portfolio/intake-valve-cleaner-1.jpg', '/projects/portfolio/intake-valve-cleaner-2.jpg', '/projects/portfolio/intake-valve-cleaner-3.jpg', '/projects/portfolio/intake-valve-cleaner-4.jpg', '/projects/portfolio/intake-valve-cleaner-5.jpg', '/projects/portfolio/intake-valve-cleaner-6.jpg'], 'A walnut-blasting adapter recreated around the intake port interface, with wall thickness, nozzle position and airflow path optimised for the target engine.', ARRAY['Automotive', 'Airflow', 'Custom Fit'], false, true, 93),
  ('snap-fit-tube', 'Snap-Fit Tube', 'mechanical', '/projects/portfolio/snap-fit-tube-0.jpg', ARRAY['/projects/portfolio/snap-fit-tube-0.jpg', '/projects/portfolio/snap-fit-tube-1.jpg', '/projects/portfolio/snap-fit-tube-2.jpg'], 'A pipe modelled to an exact length and wall thickness with an integrated snap-fit at the top, dimensioned so the part seats precisely on its mating component.', ARRAY['Snap-fit', 'Tolerances', 'CAD'], false, true, 94),
  ('microphone-housing', 'Microphone Housing', 'product', '/projects/portfolio/microphone-0.jpg', ARRAY['/projects/portfolio/microphone-0.jpg', '/projects/portfolio/microphone-1.jpg', '/projects/portfolio/microphone-2.jpg', '/projects/portfolio/microphone-3.jpg', '/projects/portfolio/microphone-4.jpg', '/projects/portfolio/microphone-5.jpg'], 'A housing concept designed around a defined internal component layout — overall body, handle, head connection and internal cavities resolved into an assembly concept.', ARRAY['Enclosure', 'Product Design', 'Audio'], false, true, 95),
  ('pants-pocket-clip', 'Pants Pocket Clip', 'product', '/projects/portfolio/pants-clip-0.jpg', ARRAY['/projects/portfolio/pants-clip-0.jpg', '/projects/portfolio/pants-clip-1.jpg', '/projects/portfolio/pants-clip-2.jpg', '/projects/portfolio/pants-clip-3.jpg', '/projects/portfolio/pants-clip-4.jpg', '/projects/portfolio/pants-clip-5.jpg'], 'A plastic pocket clip refined over several revisions — clip geometry optimised, magnet pockets added, and the result issued as a prototype-ready model with technical drawings.', ARRAY['Injection Molding', 'Magnets', 'Drawings'], false, true, 96),
  ('pinewood-derby-ballast-mold', 'Pinewood Derby Ballast Mold', 'mechanical', '/projects/portfolio/mold-pinewood-derby-cars-0.jpg', ARRAY['/projects/portfolio/mold-pinewood-derby-cars-0.jpg', '/projects/portfolio/mold-pinewood-derby-cars-1.jpg', '/projects/portfolio/mold-pinewood-derby-cars-2.jpg', '/projects/portfolio/mold-pinewood-derby-cars-3.jpg', '/projects/portfolio/mold-pinewood-derby-cars-4.jpg', '/projects/portfolio/mold-pinewood-derby-cars-5.jpg', '/projects/portfolio/mold-pinewood-derby-cars-6.jpg'], 'A multi-cavity gravity casting mould for lead ballast blocks holding 30–31 g per casting — cavities, runner and gate system, pouring inlet, vents, draft and alignment features.', ARRAY['Tooling', 'Gravity Casting', 'Multi-cavity'], false, true, 97),
  ('rat-tail-bait-mold', 'Rat Tail Bait Mold', 'mechanical', '/projects/portfolio/rat-tail-mold-0.jpg', ARRAY['/projects/portfolio/rat-tail-mold-0.jpg', '/projects/portfolio/rat-tail-mold-1.jpg', '/projects/portfolio/rat-tail-mold-2.jpg', '/projects/portfolio/rat-tail-mold-3.jpg', '/projects/portfolio/rat-tail-mold-4.jpg'], 'A six-cavity injection mould for a soft plastic rat tail bait, built around a standard injector with a 16 mm (5/8") port, with ribs and a rounded tip added to the tail.', ARRAY['Tooling', 'Soft Plastics', 'Multi-cavity'], false, true, 98),
  ('bottle-closure-assembly', 'Bottle Closure Assembly', 'product', '/projects/portfolio/bottle-cap-0.jpg', ARRAY['/projects/portfolio/bottle-cap-0.jpg', '/projects/portfolio/bottle-cap-1.jpg', '/projects/portfolio/bottle-cap-2.jpg', '/projects/portfolio/bottle-cap-3.jpg', '/projects/portfolio/bottle-cap-4.jpg', '/projects/portfolio/bottle-cap-5.jpg', '/projects/portfolio/bottle-cap-6.jpg', '/projects/portfolio/bottle-cap-7.jpg', '/projects/portfolio/bottle-cap-8.jpg', '/projects/portfolio/bottle-cap-9.jpg', '/projects/portfolio/bottle-cap-10.jpg', '/projects/portfolio/bottle-cap-11.jpg', '/projects/portfolio/bottle-cap-12.jpg', '/projects/portfolio/bottle-cap-13.jpg'], 'Revisions to an existing closure: the sleeve inner diameter was opened up to fit a mating ceramic component, with several edge-profile variants developed for comparison.', ARRAY['Revision', 'Tolerances', 'Variants'], false, true, 99),
  ('spring-loaded-fuel-spout', 'Spring-Loaded Fuel Spout', 'product', '/projects/portfolio/spout-design-0.jpg', ARRAY['/projects/portfolio/spout-design-0.jpg', '/projects/portfolio/spout-design-1.jpg', '/projects/portfolio/spout-design-2.jpg', '/projects/portfolio/spout-design-3.jpg', '/projects/portfolio/spout-design-4.jpg', '/projects/portfolio/spout-design-5.jpg', '/projects/portfolio/spout-design-6.jpg', '/projects/portfolio/spout-design-7.jpg', '/projects/portfolio/spout-design-8.jpg', '/projects/portfolio/spout-design-9.jpg', '/projects/portfolio/spout-design-10.jpg', '/projects/portfolio/spout-design-11.jpg'], 'A spring-loaded fuel spout assembly designed around sealing, smooth component travel and assembly, delivered as a CAD assembly with 2D manufacturing drawings for prototyping.', ARRAY['Assembly', 'Sealing', 'Drawings'], true, true, 100),
  ('retractable-handle-tablet-case', 'Retractable Handle Tablet Case', 'product', '/projects/portfolio/retractable-handle-strap-mechanism-0.jpg', ARRAY['/projects/portfolio/retractable-handle-strap-mechanism-0.jpg', '/projects/portfolio/retractable-handle-strap-mechanism-1.jpg', '/projects/portfolio/retractable-handle-strap-mechanism-2.jpg'], 'An early-stage concept for a tablet case with an integrated retractable handle, exploring external form and several layouts for the main components.', ARRAY['Concept', 'Mechanism', 'Consumer'], false, true, 101),
  ('xrf-scanner-stand', 'XRF Scanner Stand', 'printing', '/projects/portfolio/xrf-scanner-stand-0.jpg', ARRAY['/projects/portfolio/xrf-scanner-stand-0.jpg', '/projects/portfolio/xrf-scanner-stand-1.jpg', '/projects/portfolio/xrf-scanner-stand-2.jpg', '/projects/portfolio/xrf-scanner-stand-3.jpg', '/projects/portfolio/xrf-scanner-stand-4.jpg', '/projects/portfolio/xrf-scanner-stand-5.jpg', '/projects/portfolio/xrf-scanner-stand-6.jpg', '/projects/portfolio/xrf-scanner-stand-7.jpg', '/projects/portfolio/xrf-scanner-stand-8.jpg'], 'A stand and protective cover shaped around the scanner''s irregular geometry, refined across iterations against 3D-printed test results until the fit was stable and secure.', ARRAY['3D Print', 'Custom Fit', 'Instrumentation'], false, true, 102),
  ('speaker-mounting-bracket', 'Speaker Mounting Bracket', 'printing', '/projects/portfolio/speaker-holder-0.jpg', ARRAY['/projects/portfolio/speaker-holder-0.jpg', '/projects/portfolio/speaker-holder-1.jpg', '/projects/portfolio/speaker-holder-2.jpg', '/projects/portfolio/speaker-holder-3.jpg', '/projects/portfolio/speaker-holder-4.jpg'], 'An existing bracket recreated from reference photos and measurements, then adapted for 3D printing so it drops in as a replacement for the damaged original.', ARRAY['Reverse Eng.', '3D Print', 'Spare Part'], false, true, 103),
  ('tuff-stix-xs-extrusion', 'Tuff-Stix XS Extrusion', 'mechanical', '/projects/portfolio/tuff-stix-xs-0.jpg', ARRAY['/projects/portfolio/tuff-stix-xs-0.jpg', '/projects/portfolio/tuff-stix-xs-1.jpg', '/projects/portfolio/tuff-stix-xs-2.jpg', '/projects/portfolio/tuff-stix-xs-3.jpg'], 'An aluminium extrusion profile built to supplied specifications — wall thicknesses, exterior and interior support ribs and radius detail — and optimised for tooling preparation.', ARRAY['Extrusion', 'Aluminium', 'Profile'], false, true, 104),
  ('sun-and-rays-door-number', 'Sun & Rays Door Number', 'product', '/projects/portfolio/door-number-333-0.jpg', ARRAY['/projects/portfolio/door-number-333-0.jpg', '/projects/portfolio/door-number-333-1.jpg', '/projects/portfolio/door-number-333-2.jpg', '/projects/portfolio/door-number-333-3.jpg', '/projects/portfolio/door-number-333-4.jpg'], 'A 2D visual concept converted into a decorative door number in 3D, with ray count, shape, thickness, slope and text dimensions tuned over several rounds.', ARRAY['Decorative', 'Concept-to-Part', 'Signage'], false, true, 105),
  ('tornado-trellis', 'Tornado Trellis', 'product', '/projects/portfolio/tornado-trellis-0.jpg', ARRAY['/projects/portfolio/tornado-trellis-0.jpg', '/projects/portfolio/tornado-trellis-1.jpg', '/projects/portfolio/tornado-trellis-2.jpg', '/projects/portfolio/tornado-trellis-3.jpg', '/projects/portfolio/tornado-trellis-4.jpg', '/projects/portfolio/tornado-trellis-5.jpg'], 'A modular spiral trellis system — pedestal structure, internal support and spiral rail geometry — developed within tight spatial limits and smooth transitions.', ARRAY['Modular', 'Garden', 'Complex Geometry'], false, true, 106),
