  ('vibra-screw-plant-models', 'Vibra Screw Plant Models', 'printing', '/projects/portfolio/vibra-screw-0.jpg', ARRAY['/projects/portfolio/vibra-screw-0.jpg', '/projects/portfolio/vibra-screw-1.jpg', '/projects/portfolio/vibra-screw-2.jpg', '/projects/portfolio/vibra-screw-3.jpg', '/projects/portfolio/vibra-screw-4.jpg', '/projects/portfolio/vibra-screw-5.jpg', '/projects/portfolio/vibra-screw-6.jpg', '/projects/portfolio/vibra-screw-7.jpg', '/projects/portfolio/vibra-screw-8.jpg', '/projects/portfolio/vibra-screw-9.jpg', '/projects/portfolio/vibra-screw-10.jpg'], 'Existing DWG drawings interpreted into simplified 3D models for plant layout visualisation — accurate external shape, footprint and interfaces rather than fabrication detail.', ARRAY['Reverse Eng.', 'Plant Layout', 'DWG to 3D'], true, true, 109),
  ('worm-lure-mold', 'Worm Lure Mold', 'mechanical', '/projects/portfolio/worm-lure-mold-0.jpg', ARRAY['/projects/portfolio/worm-lure-mold-0.jpg', '/projects/portfolio/worm-lure-mold-1.jpg', '/projects/portfolio/worm-lure-mold-2.jpg', '/projects/portfolio/worm-lure-mold-3.jpg', '/projects/portfolio/worm-lure-mold-4.jpg'], 'A casting mould built around an approved worm model with a smooth section, ribbed body and tail. A core rod lets the lure mould hollow so a second colour can be injected.', ARRAY['Tooling', 'Two-Shot', 'Fishing'], false, true, 110),
  ('hyperbolic-paraboloid-structures', 'Hyperbolic Paraboloid Structures', 'printing', '/projects/portfolio/hyperbolic-paraboloid-designs-0.jpg', ARRAY['/projects/portfolio/hyperbolic-paraboloid-designs-0.jpg', '/projects/portfolio/hyperbolic-paraboloid-designs-1.jpg', '/projects/portfolio/hyperbolic-paraboloid-designs-2.jpg', '/projects/portfolio/hyperbolic-paraboloid-designs-3.jpg'], 'Complex hyperbolic paraboloid structures reconstructed from reference drawings and architectural examples, holding geometry, proportion and wall thickness from limited information.', ARRAY['Architecture', 'Complex Geometry', 'Visualisation'], false, true, 111),
  ('tunesafe-headstock-cover', 'TuneSafe Headstock Cover', 'product', '/projects/portfolio/tunesafe-guitar-0.jpg', ARRAY['/projects/portfolio/tunesafe-guitar-0.jpg', '/projects/portfolio/tunesafe-guitar-1.jpg', '/projects/portfolio/tunesafe-guitar-2.jpg'], 'A protective guitar headstock cover that stops tuning pegs being knocked. An internal support system stabilises the headstock on soft contact points without pressing the machines.', ARRAY['Product Design', 'Universal Fit', 'Music'], true, true, 112)
